query SitesList($networkId: String!) {
  sitesView(networkId: $networkId) {
    networkId
    sites {
      error {
        ...SectionErrorFields
        __typename
      }
      sites {
        ...ViewSite
        __typename
      }
      __typename
    }
    nodeCounts {
      error {
        ...SectionErrorFields
        __typename
      }
      counts {
        siteId
        total
        online
        offline
        __typename
      }
      __typename
    }
    customers {
      error {
        ...SectionErrorFields
        __typename
      }
      count
      __typename
    }
    kpis {
      error {
        ...SectionErrorFields
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment SectionErrorFields on SectionError {
  section
  code
  message
  __typename
}

